<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,reactive,ref,watch} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {api} from '../api'
import AmazonSchemaInput from '../components/AmazonSchemaInput.vue'
import CodexHandoffPanel from '../components/CodexHandoffPanel.vue'
import {variationState} from '../amazonVariations'
import {previewStatus,needsIdentifierReview,amazonRequestError,keywordReferenceError,keywordReferenceLength,DEFAULT_KEYWORD_REFERENCE_MAX_CHARS} from '../amazonValidation'
import {applySharedSelection,buildVariantSelection,sampleRow,selectionSummary,sharedVariantOptions,syncImageRules} from '../amazonSelection'
import type {SharedImageRule} from '../amazonSelection'
const generationProvider=ref<'codex'|'ai'>('codex')
const stores=ref<any[]>([]),products=ref<any[]>([]),selected=ref<any[]>([]),catalog=ref<any>({items:[],definitions:[]}),fees=ref<any>({items:[]})
const pricing=reactive<any>({}),storeId=ref(''),search=ref(''),page=ref(1),pageSize=ref(50),total=ref(0),listingStatus=ref('available'),keywords=ref('mouse pad'),type=ref(''),feeCategory=ref('')
const productCategory=ref(''),productCategories=ref<any[]>([])
const selectedProductIds=computed(()=>new Set(selected.value.map(p=>p.id)))
const pageFullySelected=computed(()=>products.value.some(p=>p.available_count>0)&&products.value.filter(p=>p.available_count>0).every(p=>selectedProductIds.value.has(p.id)))
const mergeSize=ref(20),group=ref<any>(),groupRequestId=ref('');let productRequest=0
const loading=ref(false),busy=ref(false),merge=ref(false),parentSku=ref(''),theme=ref(''),shipping=ref(''),quantity=ref(0),handling=ref(3),shippingConfirmed=ref(false),imageConfirmed=ref(false)
const keywordMaxChars=ref(DEFAULT_KEYWORD_REFERENCE_MAX_CHARS)
const copyKeywords=ref(''),preview=ref<any>(),batches=ref<any[]>([]),status=ref(''),current=ref<any>(),drawer=ref(false),currentId=ref('')
const keywordCharCount=computed(()=>keywordReferenceLength(copyKeywords.value)),keywordIssue=computed(()=>keywordReferenceError(copyKeywords.value,keywordMaxChars.value))
const batchPage=ref(1),batchTotal=ref(0),selectedBatches=ref<any[]>([]),batchTable=ref<any>();let batchRequest=0
const sharedVariantKeys=ref<string[]>([]),imageRules=ref<SharedImageRule[]>([])
const variants=ref<any[]>([]),attributes=reactive<Record<string,any>>({}),factKeys=ref<string[]>([]),editingContent=ref<any>({})
const itemAttributes=ref<Record<string,any>>({}),itemFactKeys=ref<Record<string,string[]>>({})
const errorText=ref(''),jobId=ref('');let timer:ReturnType<typeof setInterval>|undefined,disposed=false,restoring=false
const labels:Record<string,string>={waiting_codex:'等待 Codex 回填',preparing:'准备资料',needs_facts:'补充真实资料',ready:'待平台预检',validated:'待提交',validation_failed:'预检需修正',submitting:'正在提交',processing:'平台处理中',reviewing:'平台审核中',published:'已可售',created_no_stock:'已建品，库存为0',issues:'平台异常',unknown:'结果待核对',draft:'未提交'}
const definition=computed(()=>catalog.value.definitions.find((d:any)=>d.product_type===type.value&&d.parentage===(merge.value?'CHILD':'NONE')))
const variation=computed(()=>variationState(catalog.value.definitions,type.value))
const themes=computed(()=>variation.value.themes)
const variationHint=computed(()=>!type.value?'请先选择商品类目':!variation.value.loaded?'尚未读取父子变体规则，请点击“读取类目要求”':themes.value.length?'仅同一货盘基础商品，按类目支持的规格/图案建立父子变体':'已读取父子规则，当前类目没有共同可用的变体主题')
const templateOptions=computed(()=>(definition.value?.shipping_templates||[]).map((v:string,i:number)=>({value:v,label:definition.value.shipping_template_labels?.[i]||v})))
const schemaFields=computed(()=>definition.value?.fields||[])
const reserved=new Set(['brand','externally_assigned_product_identifier','supplier_declared_has_product_identifier_exemption','merchant_suggested_asin','purchasable_offer','fulfillment_availability','merchant_shipping_group','parentage_level','child_parent_sku_relationship','variation_theme','item_name','bullet_point','product_description','generic_keyword','condition_type','main_product_image_locator'])
const humanOptions=computed(()=>schemaFields.value.filter((f:any)=>!reserved.has(f.key)&&!f.key.startsWith('other_product_image_locator_')).map((f:any)=>({value:f.key,label:f.title})))
const factFields=computed(()=>schemaFields.value.filter((f:any)=>factKeys.value.includes(f.key)))
const schemaDefs=ref<any>({})
const variantOptions=computed(()=>sharedVariantOptions(variants.value))
const imageSample=computed(()=>sampleRow(variants.value,sharedVariantKeys.value))
const sharedSelection=computed(()=>applySharedSelection(variants.value,sharedVariantKeys.value,imageRules.value))
const imageRows=computed(()=>sharedSelection.value.rows)
const enabledImages=computed(()=>imageRules.value.filter(rule=>rule.action!=='exclude').length)
const selection=computed(()=>selectionSummary(imageRows.value,merge.value,mergeSize.value))
const feeInfo=computed(()=>fees.value.items?.find((x:any)=>x.key===feeCategory.value))
const feeText=computed(()=>feeInfo.value?feeInfo.value.tiers.map((x:any)=>`${x.up_to_usd==null?'其余':`至 $${x.up_to_usd}`}：${x.rate_percent}%`).join('；'):'请核对并选择官方收费类目')
function message(e:any){errorText.value=amazonRequestError(e,keywordMaxChars.value);ElMessage.error(errorText.value)}
function init(n:any):any{if(n?.$ref?.startsWith('#/$defs/'))n=schemaDefs.value[n.$ref.slice(8)]||n;if(n?.default!==undefined)return n.default;if(n?.type==='array')return [init(n.items)];if(n?.type==='object'){const o:any={};for(const [k,v] of Object.entries(n.properties||{})){if(k==='marketplace_id')o[k]='ATVPDKIKX0DER';else if(k==='language_tag')o[k]='en_US';else if(n.required?.includes(k))o[k]=init(v)}return o}if(n?.enum?.length===1)return n.enum[0];return undefined}
function clean(v:any):any{if(Array.isArray(v))return v.map(clean);if(v&&typeof v==='object')return Object.fromEntries(Object.entries(v).filter(([,x])=>x!==undefined&&x!==null&&x!=='').map(([k,x])=>[k,clean(x)]));return v}
watch(factKeys,keys=>{for(const k of Object.keys(attributes))if(!keys.includes(k))delete attributes[k];for(const k of keys)if(!(k in attributes)){const f=schemaFields.value.find((x:any)=>x.key===k);attributes[k]=init(f?.schema)}}, {deep:true})
async function loadProducts(){const sequence=++productRequest;loading.value=true;try{const q=new URLSearchParams({search:search.value,page:String(page.value),page_size:String(pageSize.value),store_id:storeId.value,listing_status:listingStatus.value,category:productCategory.value});const r=await api.get<any>(`/amazon/products?${q}`);if(sequence!==productRequest||disposed)return;products.value=r.items;total.value=r.total;productCategories.value=r.category_options||[];if(selected.value.length){const current=new Map<string,any>(r.items.map((p:any)=>[p.id,p]));selectProducts(selected.value.map(p=>current.get(p.id)||p))}}catch(e){if(sequence===productRequest)message(e)}finally{if(sequence===productRequest)loading.value=false}}
function selectProducts(rows:any[]){const wasEmpty=!selected.value.length;selected.value=rows.filter(p=>p.available_count>0);variants.value=buildVariantSelection(selected.value,variants.value);if(wasEmpty)sharedVariantKeys.value=sharedVariantOptions(variants.value).filter(option=>option.matched>0).map(option=>option.key);if(!selected.value.length){sharedVariantKeys.value=[];imageRules.value=[]}preview.value=undefined}
function clearSelection(){selected.value=[];variants.value=[];sharedVariantKeys.value=[];imageRules.value=[];preview.value=undefined;groupRequestId.value=''}
function toggleProduct(row:any){if(!storeId.value||loading.value||!row.available_count)return;selectProducts(selectedProductIds.value.has(row.id)?selected.value.filter(p=>p.id!==row.id):[...selected.value,row])}
function selectPage(){const pageIds=new Set(products.value.filter(p=>p.available_count>0).map(p=>p.id));if(pageFullySelected.value)selectProducts(selected.value.filter(p=>!pageIds.has(p.id)));else selectProducts([...selected.value.filter(p=>!pageIds.has(p.id)),...products.value.filter(p=>p.available_count>0)])}
function queryProducts(){page.value=1;void loadProducts()}
function changePage(value:number){page.value=value;void loadProducts()}
function changePageSize(value:number){pageSize.value=value;queryProducts()}
function moveImage(index:number,delta:number){const rows=[...imageRules.value],target=index+delta;if(target<0||target>=rows.length)return;[rows[index],rows[target]]=[rows[target],rows[index]];imageRules.value=rows}
function setImageAction(index:number,action:string){if(!['main','additional','exclude'].includes(action))return;const rows=imageRules.value.map((rule,n)=>({...rule,action:action==='main'&&n!==index&&rule.action==='main'?'additional' as const:rule.action}));rows[index].action=action as SharedImageRule['action'];if(!rows.some(rule=>rule.action==='main')){const replacement=rows.find(rule=>rule.action!=='exclude');if(replacement)replacement.action='main'}imageRules.value=rows}
function checkSharedSelection(){if(keywordIssue.value)throw new Error(keywordIssue.value);if(!imageRows.value.length)throw new Error('请至少选择一个上架规格');if(sharedSelection.value.issues.length)throw new Error(sharedSelection.value.issues.slice(0,3).join('；'))}
watch(imageSample,row=>{imageRules.value=syncImageRules(row,imageRules.value)})
watch(()=>JSON.stringify(imageRows.value.map(row=>[row.variant.id,row.images])),()=>{if(!restoring)imageConfirmed.value=false})
async function loadCatalog(){if(!storeId.value)return;const store=storeId.value,productType=type.value;const result=await api.get<any>(`/amazon/stores/${store}/catalog?product_type=${encodeURIComponent(productType)}`);if(store!==storeId.value||productType!==type.value||disposed)return;catalog.value=result}
async function waitJob(id:string){jobId.value=id;for(let n=0;n<150&&!disposed;n++){const j=await api.get<any>(`/jobs/${id}`);if(j.status==='completed'){jobId.value='';return}if(['failed','cancelled','action_required','paused'].includes(j.status))throw new Error(j.error_message||'任务需要处理');await new Promise(r=>setTimeout(r,2000))}ElMessage.info('任务仍在原电脑运行，可在任务中心继续查看')}
async function readCatalog(refresh=false){busy.value=true;try{const r=await api.post<any>(`/amazon/stores/${storeId.value}/catalog`,{keywords:keywords.value,refresh});if(r.job_id)await waitJob(r.job_id);await loadCatalog()}catch(e){message(e)}finally{busy.value=false}}
async function readDefinition(refresh=false){busy.value=true;try{const r=await api.post<any>(`/amazon/stores/${storeId.value}/catalog`,{product_type:type.value,variations:true,refresh});if(r.job_id)await waitJob(r.job_id);await loadCatalog()}catch(e){message(e)}finally{busy.value=false}}
function payload(){return {generation_provider:generationProvider.value,store_id:storeId.value,product_type:type.value,fee_category:feeCategory.value,pricing:{...pricing},items:imageRows.value.map(x=>({product_id:x.product.id,variant_id:x.variant.id,images:x.images,attributes:x.attributes||{}})),parent_sku:'',merge:merge.value,merge_group_size:mergeSize.value,variation_theme:merge.value?theme.value:'',shipping_template:shipping.value,quantity:quantity.value,handling_days:handling.value,attributes:clean(attributes),keywords:copyKeywords.value,free_shipping_confirmed:shippingConfirmed.value,main_image_confirmed:imageConfirmed.value}}
async function getPreview(){busy.value=true;errorText.value='';try{checkSharedSelection();preview.value=await api.post('/amazon/group-preview',payload())}catch(e){message(e)}finally{busy.value=false}}
async function saveDefaults(){try{await api.put('/settings/amazon_us_pricing',{value:{...pricing}});ElMessage.success('美国站定价默认值已保存')}catch(e){message(e)}}
async function prepare(){busy.value=true;errorText.value='';try{checkSharedSelection();groupRequestId.value||=crypto.randomUUID().replaceAll('-','');group.value=await api.post<any>('/amazon/batch-groups',{...payload(),request_id:groupRequestId.value});ElMessage.success(`已建立 ${group.value.batches.length} 批，计划 ${group.value.link_count} 个链接`);clearSelection();await loadProducts();await loadBatches();await openBatch(group.value.batch_ids[0])}catch(e){message(e)}finally{busy.value=false}}
async function loadBatches(){const request=++batchRequest;const r=await api.get<any>(`/amazon/batches?store_id=${storeId.value}&status=${status.value}&page=${batchPage.value}&grouped=true`);if(request!==batchRequest||disposed)return;batches.value=r.items;batchTotal.value=r.total}
function queryBatches(){batchPage.value=1;selectedBatches.value=[];batchTable.value?.clearSelection();void loadBatches().catch(message)}
function changeBatchPage(value:number){batchPage.value=value;selectedBatches.value=[];batchTable.value?.clearSelection();void loadBatches().catch(message)}
async function removeBatches(rows:any[]){const ids=[...new Set(rows.flatMap(row=>row.batch_ids||[row.id]))];if(!ids.length||busy.value)return;try{await ElMessageBox.confirm(`删除所选 ${rows.length} 个批次，共 ${rows.reduce((n,row)=>n+(row.count||0),0)} 个子商品？未提交任务将停止，产品释放回对应店铺的可上架列表。`,'删除未提交批次',{confirmButtonText:'删除并释放产品',cancelButtonText:'保留',type:'warning'});busy.value=true;const r=await api.post<any>('/amazon/batches/remove',{batch_ids:ids});if(ids.includes(currentId.value)){drawer.value=false;currentId.value='';current.value=undefined;group.value=undefined}selectedBatches.value=[];batchTable.value?.clearSelection();groupRequestId.value='';preview.value=undefined;await loadProducts();await loadBatches();ElMessage.success(`已删除批次，释放 ${r.released_count} 个上架规格`)}catch(e:any){if(e!=='cancel'&&e!=='close')message(e)}finally{busy.value=false}}
async function openBatch(id:string){try{currentId.value=id;current.value=await api.get(`/amazon/batches/${id}`);drawer.value=true;restoring=true;clearSelection();const snap=current.value.snapshot;storeId.value=snap.store_id;mergeSize.value=snap.selection_group?.merge_group_size||20;group.value=snap.selection_group?await api.get(`/amazon/batch-groups/${snap.selection_group.id}`):undefined;type.value=snap.product_type;merge.value=!!snap.parent_sku;parentSku.value=snap.parent_sku;theme.value=snap.variation_theme;shipping.value=snap.shipping_template;quantity.value=snap.quantity;handling.value=snap.handling_days;shippingConfirmed.value=snap.free_shipping_confirmed;feeCategory.value=snap.fee_category;Object.assign(pricing,snap.pricing||{});copyKeywords.value=snap.keywords||'';generationProvider.value=snap.generation_provider||'ai';await nextTick();await loadCatalog();await loadProducts();const saved=snap.attributes||{};for(const k of Object.keys(attributes))delete attributes[k];Object.assign(attributes,JSON.parse(JSON.stringify(saved)));factKeys.value=Object.keys(saved);editingContent.value=JSON.parse(JSON.stringify(current.value.draft.content||{}));itemAttributes.value=Object.fromEntries(snap.items.map((x:any)=>[x.sku,JSON.parse(JSON.stringify(x.attributes||{}))]));itemFactKeys.value=Object.fromEntries(snap.items.map((x:any)=>[x.sku,Object.keys(x.attributes||{})]));imageConfirmed.value=snap.main_image_confirmed}catch(e){message(e)}finally{restoring=false}}
function selectItemFacts(sku:string,keys:string[]){itemAttributes.value[sku]??={};for(const k of Object.keys(itemAttributes.value[sku]))if(!keys.includes(k))delete itemAttributes.value[sku][k];for(const k of keys)if(!(k in itemAttributes.value[sku]))itemAttributes.value[sku][k]=init(schemaFields.value.find((f:any)=>f.key===k)?.schema)}
async function refreshCurrent(){if(!currentId.value)return;const id=currentId.value;const previous=current.value;const fresh=await api.get<any>(`/amazon/batches/${id}`);if(currentId.value!==id)return;current.value=fresh;if(['waiting_codex','preparing'].includes(previous?.status)&&['ready','needs_facts'].includes(fresh.status))editingContent.value=JSON.parse(JSON.stringify(fresh.draft.content||{}))}
async function saveFacts(){busy.value=true;try{await api.patch(`/amazon/batches/${currentId.value}/facts`,{attributes:clean(attributes),item_attributes:clean(itemAttributes.value),content:editingContent.value,main_image_confirmed:imageConfirmed.value});await refreshCurrent();ElMessage.success('资料已保存，需重新平台预检')}catch(e){message(e)}finally{busy.value=false}}
async function refreshBasis(){busy.value=true;try{await api.post(`/amazon/batches/${currentId.value}/refresh-basis`);await openBatch(currentId.value);ElMessage.success('成本与类目依据已更新，请重新预检')}catch(e){message(e)}finally{busy.value=false}}
async function operate(kind:string){busy.value=true;try{if(kind==='submit')await ElMessageBox.confirm(`向 ${current.value.snapshot.store_name} 正式提交 ${current.value.snapshot.items.length} 个 FBM 子商品，按已预检的价格、库存及配送模板执行。`,'确认本批次上架',{confirmButtonText:'正式提交',cancelButtonText:'返回检查'});const body=kind==='submit'?{draft_digest:current.value.result.validated_digest}:undefined;const r=await api.post<any>(`/amazon/batches/${currentId.value}/${kind}`,body);ElMessage.success('任务已交给原执行电脑');jobId.value=r.job_id;await refreshCurrent();await loadBatches()}catch(e:any){if(e!=='cancel'&&e!=='close')message(e)}finally{busy.value=false}}
watch(storeId,async()=>{if(restoring)return;clearSelection();group.value=undefined;page.value=1;batchPage.value=1;selectedBatches.value=[];batchTable.value?.clearSelection();type.value='';shipping.value='';shippingConfirmed.value=false;catalog.value={items:[],definitions:[]};try{await loadProducts();if(storeId.value){await loadCatalog();await loadBatches()}}catch(e){message(e)}})
watch(type,()=>{if(restoring)return;preview.value=undefined;theme.value='';shipping.value='';shippingConfirmed.value=false;merge.value=false;schemaDefs.value={};void loadCatalog().catch(message)})
watch(definition,d=>{schemaDefs.value=d?.schema_definitions||{};if(!restoring)factKeys.value=[...new Set([...factKeys.value,...(d?.required||[]).filter((k:string)=>!reserved.has(k)&&!['material','special_feature','item_shape','item_length_width'].includes(k))])]})
watch(merge,()=>{preview.value=undefined;if(!merge.value)theme.value='';else if(themes.value.length===1)theme.value=themes.value[0]})
watch(status,queryBatches)
watch(()=>JSON.stringify(payload()),()=>{groupRequestId.value='';preview.value=undefined})
onMounted(async()=>{try{const [s,p]=await Promise.all([api.get<any>('/stores'),api.get<any>('/amazon/pricing')]);stores.value=s.items.filter((x:any)=>x.platform==='amazon'&&x.enabled);Object.assign(pricing,p.defaults);fees.value=p.commissions;keywordMaxChars.value=p.limits?.keyword_reference_max_chars||DEFAULT_KEYWORD_REFERENCE_MAX_CHARS;restoring=true;if(stores.value.length===1)storeId.value=stores.value[0].id;await nextTick();restoring=false;await loadProducts();await loadBatches();if(storeId.value)await loadCatalog();timer=setInterval(async()=>{try{await loadBatches();if(drawer.value)await refreshCurrent()}catch{/* keep current view on a temporary outage */}},10000)}catch(e){message(e)}})
onUnmounted(()=>{disposed=true;if(timer)clearInterval(timer)})
</script>
<template>
  <div class="amz-page">
    <el-alert title="Amazon 美国站 · FBM · generic · GTIN 豁免需平台核验" description="人工选定类目，默认由 Codex 接手准备英文文案。售价、主图、产品事实和父子变体经核验后提交；建品接受不等于可售。" type="info" :closable="false"/>
    <div class="panel"><h3>1. 选择店铺与 Amazon POD 产品</h3>
      <div class="toolbar"><el-select v-model="storeId" placeholder="目标 Amazon 店铺"><el-option v-for="s in stores" :key="s.id" :label="s.name" :value="s.id"/></el-select><RouterLink to="/stores">管理店铺及授权</RouterLink><el-input v-model="search" clearable placeholder="SKU / 商品名称" style="width:250px" @keyup.enter="queryProducts" @clear="queryProducts"/><el-select v-model="productCategory" filterable clearable placeholder="全部产品分类" style="width:280px" @change="queryProducts"><el-option v-for="c in productCategories" :key="c.label" :value="c.label" :label="`${c.label}（${c.count}）`"/></el-select><el-select v-model="listingStatus" style="width:210px" @change="queryProducts"><el-option label="未上架且未进入批次" value="available"/><el-option label="已上架 / 已进入批次" value="occupied"/><el-option label="全部产品" value="all"/></el-select><el-button @click="queryProducts">查询</el-button></div>
      <div class="toolbar"><el-button :disabled="!storeId||loading" @click="selectPage">{{pageFullySelected?'取消本页':'全选本页'}}</el-button><el-button :disabled="!selected.length" @click="clearSelection">清空已选</el-button><span>已选 {{selected.length}} 个产品 · {{selection.count}} 个上架规格（跨页保留）</span></div>
      <div class="publish-product-grid" v-loading="loading">
        <article v-for="row in products" :key="row.id" class="publish-product-card" :class="{selected:selectedProductIds.has(row.id),unavailable:!row.available_count}" role="checkbox" :aria-checked="selectedProductIds.has(row.id)" :aria-disabled="!storeId||!row.available_count" :tabindex="storeId&&row.available_count?0:-1" @click="toggleProduct(row)" @keydown.enter.self.prevent="toggleProduct(row)" @keydown.space.self.prevent="toggleProduct(row)">
          <div class="publish-card-image"><el-image v-if="row.thumbnail_url" :src="row.thumbnail_url" fit="cover" lazy/><div v-else class="publish-no-image">暂无图片</div><span class="select-mark">{{selectedProductIds.has(row.id)?'✓':row.available_count?'+':'—'}}</span><el-tag class="source-mark" size="small">Amazon POD</el-tag></div>
          <div class="publish-card-body"><h3 :title="row.name">{{row.name}}</h3><div class="product-code">{{row.sku}}</div><div class="sku-section"><b>全部 SKU（{{row.variants.length}}）</b><span v-for="v in row.variants" :key="v.id" class="full-sku">{{v.sku}} · {{v.size||v.specification}}</span></div><div class="card-category" :title="row.category">{{row.category||'未分类'}}</div><div class="card-footer"><span>{{row.assets.length}} 张图片</span><el-tag v-if="storeId&&row.available_count" type="success" size="small">{{row.available_count}} 个规格可上架</el-tag><el-tag v-else-if="storeId" type="info" size="small">已上架 / 已入批次</el-tag><span v-else>请先选择店铺</span></div><div v-for="v in row.variants.filter((v:any)=>!v.available)" :key="v.id" class="occupied-variant"><el-button link type="primary" @click.stop="openBatch(v.listing.batch_id)">{{v.sku}} · {{labels[v.listing.status]||v.listing.status}}</el-button></div></div>
        </article>
        <el-empty v-if="!loading&&!products.length" description="没有符合条件的产品"/>
      </div>
      <el-pagination class="product-pagination" :current-page="page" :page-size="pageSize" :page-sizes="[20,50,100]" :total="total" layout="total, sizes, prev, pager, next, jumper" @current-change="changePage" @size-change="changePageSize"/>
    </div>
    <div v-if="variants.length" class="panel shared-settings">
      <h3>2. 统一选择本批上架规格与图片顺序</h3>
      <p class="hint">只展示一个产品作为样例；规格、主图、附图和停用规则自动应用到本批同类产品。</p>
      <el-checkbox-group v-model="sharedVariantKeys" class="shared-specs"><el-checkbox v-for="option in variantOptions" :key="option.key" :value="option.key" border><b>{{option.label}}</b><small>{{option.color}} · 匹配 {{option.matched}} / {{option.total}} 个产品</small></el-checkbox></el-checkbox-group>
